createEvent(raidStyle) {
    if (this.connections.length === 0) {
        console.log("No additional connections available.");
        return;
    }

    let countConnectionsToInclude;
    if (raidStyle === "1by1") {
        countConnectionsToInclude = 1;
    } else if (raidStyle === "xkey") {
        countConnectionsToInclude = 3;
    } else {
        console.error("Unrecognized raid style.");
        return;
    }

    while (this.connections.length > 0) {
        const group = [];
        const connectionsToInclude = this.connections.slice(0, countConnectionsToInclude); // Copy the first countConnectionsToInclude elements
        for (const connection of connectionsToInclude) {
            const psk = connection.psk;
            group.push({ connection, psk, hasStash: false });
        }

        console.log(`Group ${this.groups.length + 1} formed with ${group.length} connections.`);
        this.groups.push(group);
    }
}

